<?php
namespace App\Support;
use App\Models\{User,Apprentice,ReviewAppointment as Appointment};
use Illuminate\Support\Facades\DB;
class ReviewMeetingFollowup {
 public const PARTICIPATION=['Reported present','Reported absent','Not checked'];
 public static function reported(Appointment $p):bool {try{$o=$p->outcome;return ReviewAppointments::intact($p)&&$p->state==='Reported'&&ReviewAppointments::publicationValid($p)&&$o&&$o['version']===$p->version&&$o['source_hash']===$p->source_hash&&$o['scheduled_version']===ReviewAppointments::scheduleVersion($p)&&in_array($o['kind'],['Held','Partial','Not held'],true);}catch(\Throwable){return false;}}
 public static function record(User $actor,int $auth,Appointment $record,int $version,array $data):void {DB::transaction(function()use($actor,$auth,$record,$version,$data):void {$a=Apprentice::whereKey($record->apprentice_id)->lockForUpdate()->firstOrFail();$u=ReviewAppointments::actor($actor,$auth);abort_unless(ReviewAppointments::staff($u,$a),403);$p=Appointment::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!ReviewAppointments::published($p)||!ReviewAppointments::current($p,true)||$p->version!==$version||$p->ends_at->gt(now())){ReviewAppointments::fail('Record actual operational outcome after the appointment ended, against its current published source.');}$kind=$data['kind'];if(!in_array($kind,['Held','Partial','Not held'],true)||array_keys($data['participation'])!==array_keys(ReviewAppointments::ROLES)||count(array_filter($data['participation'],fn($v)=>!in_array($v,self::PARTICIPATION,true)))){ReviewAppointments::fail('Check each reported participant, without inferring from availability.');}$present=count(array_filter($data['participation'],fn($v)=>$v==='Reported present'));if($kind==='Held'&&$present!==3||$kind==='Partial'&&($present===0||$present===3)){ReviewAppointments::fail('Held needs all three reported present; Partial needs some but not all. This is staff-reported logistics, not verified review completion.');}$followup=[];if($kind!=='Held'){$owner=User::find($data['owner_id']??null);if(!$owner||!ReviewAppointments::staff($owner,$a)||empty($data['due_on'])||$data['due_on']<today()->toDateString()||!filled($data['action']??null)){ReviewAppointments::fail('Partial/not-held outcome needs an eligible current staff owner, current/future date and safe next action.');}$followup=['owner_id'=>$owner->id,'due_on'=>$data['due_on'],'action'=>$data['action']];}$scheduled=$p->version;$p->version++;$p->state='Reported';$p->active_slot=null;$p->outcome=['version'=>$p->version,'source_hash'=>$p->source_hash,'scheduled_version'=>$scheduled,'kind'=>$kind,'participation'=>$data['participation'],'note'=>$data['note'],'followup'=>$followup,'by'=>$u->id,'at'=>now()->toIso8601String()];$p->save();ReviewAppointments::event($p,$u,'operational_outcome',['kind'=>$kind,'participation'=>$data['participation'],'no_review_completion_created'=>true]);},3);}
 public static function link(User $actor,int $auth,Appointment $old,int $version,int $followupVersion,Appointment $replacement,int $replacementVersion,string $note):void {DB::transaction(function()use($actor,$auth,$old,$version,$followupVersion,$replacement,$replacementVersion,$note):void {$a=Apprentice::whereKey($old->apprentice_id)->lockForUpdate()->firstOrFail();$u=ReviewAppointments::actor($actor,$auth);abort_unless(ReviewAppointments::staff($u,$a),403);$rows=Appointment::whereIn('id',[$old->id,$replacement->id])->orderBy('id')->lockForUpdate()->get()->keyBy('id');$p=$rows->get($old->id);$next=$rows->get($replacement->id);if(!$p||!$next||$p->id===$next->id||$p->apprentice_id!==$next->apprentice_id||$p->version!==$version||$p->followup_version!==$followupVersion||!self::reported($p)||$p->outcome['kind']==='Held'||$next->version!==$replacementVersion||!ReviewAppointments::published($next)||!ReviewAppointments::current($next,true)||!$next->starts_at->gt(now())||!$next->starts_at->gt($p->ends_at)){ReviewAppointments::fail('Link one current future published replacement for the same learner; availability/signatures are never carried forward.');}$before=$p->followup;$p->followup_version++;$p->followup=['version'=>$p->followup_version,'old_version'=>$p->version,'outcome_hash'=>ReviewedImports::hash($p->outcome),'replacement_id'=>$next->id,'replacement_version'=>$next->version,'replacement_hash'=>$next->source_hash,'by'=>$u->id,'at'=>now()->toIso8601String(),'note'=>$note];$p->save();ReviewAppointments::event($p,$u,'replacement_linked',['before'=>$before,'replacement_id'=>$next->id,'followup_version'=>$p->followup_version]);},3);}
 public static function position(Appointment $p):array {try{if(!self::reported($p)){return ['needed'=>false,'replacement_current'=>false,'label'=>'No verified operational outcome'];}if($p->outcome['kind']==='Held'){return ['needed'=>false,'replacement_current'=>false,'label'=>'Staff reported held; formal review/sign-off remains separate'];}$f=$p->followup;$next=$f?Appointment::find($f['replacement_id']):null;$current=$f&&$next&&$f['version']===$p->followup_version&&$f['old_version']===$p->version&&$f['outcome_hash']===ReviewedImports::hash($p->outcome)&&$next->apprentice_id===$p->apprentice_id&&$next->version===$f['replacement_version']&&$next->source_hash===$f['replacement_hash']&&ReviewAppointments::published($next)&&ReviewAppointments::current($next)&&$next->starts_at->gt(now());return ['needed'=>!$current,'replacement_current'=>(bool)$current,'label'=>$current?'Current replacement linked; not review completion':'Rebooking/follow-up needs checking','owner_needs_check'=>!($owner=User::find($p->outcome['followup']['owner_id']??null))||!ReviewAppointments::staff($owner,Apprentice::findOrFail($p->apprentice_id)),'overdue'=>!$current&&($p->outcome['followup']['due_on']??'9999-12-31')<today()->toDateString()];}catch(\Throwable){return ['needed'=>true,'replacement_current'=>false,'label'=>'Follow-up evidence needs checking'];}}
}
